#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct CommitRecord {
    pub trigger: Trigger,
    pub description_source: DescriptionSource,
    pub task: Option<String>,
