#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub(crate) struct CommitOperation {
    /// Stable identity reserved before the operation starts, independent of
    /// the outcome commit's object id and this machine's numeric index.
    pub id: String,
    pub kind: OperationKind,
    pub status: OperationStatus,
    pub before: Option<String>,
    pub to: Option<String>,
    pub undoes: Option<String>,
    pub applied: Option<String>,
    pub affected: Vec<String>,
    pub sources: Vec<OperationSource>,
    pub directories: Vec<String>,
    pub directory_modes: BTreeMap<String, u32>,
}

    recover_records(store, tracked, pending)
}

fn recover_records(
    store: &Store,
    tracked: &TrackedSet,
    pending: Vec<(PathBuf, Pending)>,
) -> Result<()> {
    let state_dir = store.state_dir();
    if pending.is_empty() {
        store::remove_marker_in(state_dir);
        return Ok(());
    }
    // An outcome commit may have reached Git before its derived index was
    // written. Rebuild before deciding whether recovery must record it.
    let index = store.rebuild_index()?;
    let _store_lock = store.lock()?;
    let mut recorded_operations = BTreeSet::new();
    for entry in &index.entries {
        if let Some(operation) = store::read_meta_cache_in(state_dir, &entry.uuid)?
            .and_then(|checkpoint| checkpoint.operation)
        {
            recorded_operations.insert(operation.id);
        }
    }
    for (path, mut record) in pending {
        let interrupted = record
            .checkpoint
            .operation
            .as_ref()
            .is_some_and(|operation| operation.status == OperationStatus::Pending);
        let overlays: Vec<_> = promotion
            .overlays
            .into_iter()
            .map(|(path, object)| Overlay { path, object })
            .collect();
        let next = repo.compose(&tree, &overlays)?;
        let mut manifest = Manifest::read(repo, &next)?
            .ok_or_else(|| eyre::eyre!("before commit is missing enrollment metadata"))?;
        manifest.capture_permissions(&tracked.entries, &promotion.modes)?;
        let next = manifest.write(repo, &next)?;
        if next == tree && promotion.modes == checkpoint.tree.modes {
            return Ok(None);
        }
        checkpoint.changes = changes_from(repo, Some(&tree), &next, Some(checkpoint.uuid.clone()))?;
        checkpoint.uuid = store::new_uuid();
        checkpoint.created_at = store::now_rfc3339();
        checkpoint.tree.snapshot = Some(next);
        checkpoint.tree.modes = promotion.modes;
        checkpoint.operation = None;
        let mut index = store::load_index_in(&self.state_dir)?;
        if index.entries.last().map(|entry| entry.commit.as_str()) != Some(head.as_str()) {
            index = self.rebuild_index_locked()?;
        }
        self.commit_record_locked(checkpoint, index, None).map(Some)
    }
}

